    description: {
      de: "Das Nationales Pantheon ist die letzte Ruhestätte venezolanischer Nationalhelden, darunter Simón Bolívar.",
      hu: "A Nemzeti Panteon Venezuela nemzeti hőseinek, köztük Simón Bolívarnak a végső nyughelye.",
      ro: "Panteonul Național este locul de odihnă final al eroilor naționali venezueleni, inclusiv Simón Bolívar.",
      en: "The National Pantheon is the final resting place of Venezuelan national heroes, including Simón Bolívar.",
      es: "El Panteón Nacional es el lugar de descanso final de los héroes nacionales venezolanos, incluido Simón Bolívar.",
      pt: "O Panteão Nacional é o local de descanso final dos heróis nacionais venezuelanos, incluindo Simón Bolívar.",
      fr: "Le Panthéon National est la dernière demeure des héros nationaux vénézuéliens, dont Simón Bolívar.",
    },
    descriptionAdvanced: {
      de: "Das Panteón Nacional de Venezuela in Caracas ist die letzte Ruhestätte der bedeutendsten Helden der venezolanischen Geschichte. Das Gebäude wurde ursprünglich auf den Ruinen der Kirche der Heiligen Dreifaltigkeit errichtet, die durch das Erdbeben von 1812 zerstört worden war. Im Jahr 1874 ordnete Präsident Antonio Guzmán Blanco die Umwandlung des Geländes in ein Nationalheiligtum an, um die sterblichen Überreste von Simón Bolívar und anderen Patrioten aufzunehmen. Die Architektur kombiniert neugotische Elemente mit monumentalen Innenräumen, die mit Gemälden von Tito Salas geschmückt sind und wichtige Momente des Unabhängigkeitskampfes darstellen. Das Gebäude wurde mehrfach erweitert, zuletzt durch den Bau des modernen Mausoleums von Simón Bolívar, das durch seine auffällige weiße Struktur besticht. Das Panteón ist nicht nur ein Friedhof, sondern ein Symbol der nationalen Identität und des republikanischen Erbes des Landes. Es beherbergt über 140 Gedenkstätten und Gräber von Persönlichkeiten aus Politik, Militär und Wissenschaft.",
      hu: "A caracasi Panteón Nacional de Venezuela a venezuelai történelem legjelentősebb hőseinek végső nyughelye. Az épület eredetileg a Szentháromság-templom (Iglesia de la Santísima Trinidad) romjaira épült, amelyet az 1812-es földrengés rombolt le. 1874-ben Antonio Guzmán Blanco elnök elrendelte a helyszín nemzeti panteonná alakítását, hogy ott helyezzék el Simón Bolívar és más patrióták földi maradványait. Az építészet neogótikus elemeket ötvöz monumentális belső terekkel, amelyeket Tito Salas festményei díszítenek, bemutatva a függetlenségi harc fontos pillanatait. Az épületet többször bővítették, legutóbb Simón Bolívar modern mauzóleumának felépítésével, amely feltűnő fehér szerkezetével tűnik ki. A Panteón nem csupán temetkezési hely, hanem a nemzeti identitás és az ország köztársasági örökségének szimbóluma is. Több mint 140 emlékműnek és sírnak ad helyet, ahol politikai, katonai és tudományos kiválóságok nyugszanak.",
      ro: "Panteón Nacional de Venezuela din Caracas este locul de odihnă finală al celor mai importanți eroi ai istoriei venezuelene. Clădirea a fost ridicată inițial pe ruinele Bisericii Sfintei Treimi, care a fost distrusă de cutremurul din 1812. În 1874, președintele Antonio Guzmán Blanco a ordonat transformarea sitului într-un panteon național pentru a găzdui rămășițele pământești ale lui Simón Bolívar și ale altor patrioți. Arhitectura combină elemente neogotice cu interioare monumentale decorate cu picturi de Tito Salas, care înfățișează momente cruciale ale luptei pentru independență. Clădirea a fost extinsă de mai multe ori, cel mai recent prin construcția modernului mausoleu al lui Simón Bolívar, care se remarcă prin structura sa albă frapantă. Panteonul nu este doar un cimitir, ci un simbol al identității naționale și al moștenirii republicane a țării. Acesta găzduiește peste 140 de monumente și morminte ale unor personalități din politică, armată și știință.",
      en: "The National Pantheon of Venezuela in Caracas is the final resting place of the most significant heroes in Venezuelan history. The building was originally constructed on the ruins of the Holy Trinity Church, which had been destroyed by the 1812 earthquake. In 1874, President Antonio Guzmán Blanco decreed the transformation of the site into a national pantheon to house the remains of Simón Bolívar and other patriots. The architecture combines Neo-Gothic elements with monumental interiors decorated with paintings by Tito Salas, depicting crucial moments of the independence struggle. The building has been expanded several times, most recently with the construction of the modern Mausoleum of Simón Bolívar, which stands out with its striking white structure. The Pantheon is not merely a cemetery but a symbol of national identity and the country's republican heritage. It houses over 140 memorials and tombs of figures from politics, the military, and science.",
      es: "El Panteón Nacional de Venezuela es un lugar sagrado de la memoria nacional. Construido originalmente como la iglesia 'Santísima Trinidad', el edificio fue declarado en el siglo XIX como el lugar de descanso final para las personalidades más destacadas de la historia de Venezuela. Los magníficos murales y el diseño arquitectónico subrayan la importancia de los héroes aquí enterrados, como Simón Bolívar. Es un monumento central que preserva profundamente la identidad e historia del país.",
      pt: "O Panteão Nacional da Venezuela é um lugar sagrado de memória nacional. Originalmente construído como a igreja 'Santíssima Trindade', o edifício foi declarado no século XIX como o local de descanso final para as personalidades mais proeminentes da história da Venezuela. As magníficas pinturas murais e o design arquitetónico sublinham a importância dos heróis aqui enterrados, como Simón Bolívar. É um monumento central que preserva profundamente a identidade e a história do país.",
      fr: "Le Panthéon National du Venezuela est un lieu sacré de la mémoire nationale. Anciennement église « Santísima Trinidad », l'édifice a été déclaré au XIXe siècle comme dernière demeure des personnalités les plus marquantes de l'histoire vénézuélienne. Les magnifiques peintures murales et la conception architecturale soulignent l'importance des héros qui y reposent, comme Simón Bolívar. C'est un monument central qui préserve profondément l'identité et l'histoire du pays.",
    },
