    coords: [-71.6033, 10.9765],
    name: {
      de: "Festung San Carlos de la Barra",
      hu: "San Carlos de la Barra Erőd",
      ro: "Cetatea San Carlos de la Barra",
      en: "San Carlos de la Barra Fortress"},
    description: {
      de: "Eine historische Sternfestung aus dem 17. Jahrhundert, die den Golf von Venezuela vor Piraten schützte.",
      hu: "Egy 17. századi történelmi csillagerőd, amely a Venezuelai-öblöt védte a kalózoktól.",
      ro: "O cetate istorică în formă de stea din secolul al XVII-lea care proteja Golful Venezuelei de pirați.",
      en: "A historic 17th-century star fortress that protected the Gulf of Venezuela from pirates.",
      es: "Una histórica fortaleza en estrella del siglo XVII que protegía el Golfo de Venezuela de los piratas.",
      pt: "Uma histórica fortaleza em estrela do século XVII que protegia o Golfo da Venezuela dos piratas.",
      fr: "Un fort historique en étoile du XVIIe siècle qui protégeait le golfe du Venezuela contre les pirates.",
    },
    descriptionAdvanced: {
      de: "Das Castillo de San Carlos de la Barra ist eine historische Festung am Eingang zum Maracaibo-See im Bundesstaat Zulia. Es wurde im 17. Jahrhundert erbaut, um die Stadt Maracaibo vor den ständigen Angriffen von Piraten und Korsaren zu schützen, die das Karibische Meer unsicher machten. Die Festung zeichnet sich durch ihre strategische Lage auf einer Halbinsel aus, die den Zugang zur Bucht kontrolliert. Im Laufe der Jahrhunderte war das Castillo Schauplatz zahlreicher militärischer Auseinandersetzungen, darunter die Blockade von 1903 durch deutsche und britische Schiffe. Die Struktur besteht aus Kalkstein und Korallenstein, was ihr eine enorme Widerstandsfähigkeit verleiht. Während der Diktatur von Juan Vicente Gómez diente die Festung als berüchtigtes Gefängnis für politische Gefangene. Heute ist die Anlage als Nationaldenkmal geschützt und für Besucher zugänglich, die die Kanonenbatterien und die dunklen Kerker besichtigen können. Die Festung bietet zudem einen weiten Blick über die Meerenge von Maracaibo und zeugt von der kolonialen Verteidigungsarchitektur Venezuelas.",
      hu: "A Castillo de San Carlos de la Barra egy történelmi erőd a Maracaibo-tó bejáratánál, Zulia államban. A 17. században épült, hogy megvédje Maracaibo városát a Karib-tengert járó kalózok és korzárok folyamatos támadásaitól. Az erőd stratégiai elhelyezkedése egy félszigeten található, amely ellenőrzi az öbölbe való belépést. Az évszázadok során a kastély számos katonai összecsapás helyszíne volt, beleértve az 1903-as blokádot, amelyet német és brit hajók hajtottak végre. A szerkezet mészkőből és korallkőből készült, ami rendkívüli ellenálló képességet kölcsönöz neki. Juan Vicente Gómez diktatúrája alatt az erőd hírhedt börtönként szolgált a politikai foglyok számára. Ma a létesítmény nemzeti műemlékként védett és látogatható, a turisták megtekinthetik az ágyúütegeket és a sötét börtöncellákat. Az erőd széles kilátást nyújt a Maracaibo-szorosra, és ékes bizonyítéka Venezuela gyarmati védelmi építészetének.",
      ro: "Castillo de San Carlos de la Barra este o fortăreață istorică situată la intrarea în Lacul Maracaibo, în statul Zulia. A fost construită în secolul al XVII-lea pentru a proteja orașul Maracaibo de atacurile constante ale piraților și corsarilor care cutreierau Marea Caraibilor. Fortăreața se remarcă prin locația sa strategică pe o peninsulă care controlează accesul în golf. De-a lungul secolelor, castelul a fost scena a numeroase confruntări militare, inclusiv blocada din 1903 realizată de nave germane și britanice. Structura este realizată din piatră de calcar și corali, ceea ce îi conferă o rezistență enormă. În timpul dictaturii lui Juan Vicente Gómez, fortăreața a servit ca închisoare notorie pentru deținuții politici. Astăzi, situl este protejat ca monument național și este deschis vizitatorilor, care pot vedea bateriile de tunuri și temnițele întunecate. Fortăreața oferă, de asemenea, o vedere largă asupra strâmtorii Maracaibo și depune mărturie despre arhitectura defensivă colonială a Venezuelei.",
      en: "The San Carlos de la Barra Fortress is a historical fortification located at the entrance to Lake Maracaibo in Zulia State. It was built in the 17th century to protect the city of Maracaibo from the constant attacks of pirates and corsairs who roamed the Caribbean Sea. The fortress stands out for its strategic location on a peninsula that controls access to the bay. Over the centuries, the castle has been the scene of numerous military confrontations, including the 1903 blockade by German and British ships. The structure is made of limestone and coral stone, giving it enormous resistance. During the dictatorship of Juan Vicente Gómez, the fortress served as a notorious prison for political prisoners. Today, the facility is protected as a national monument and is open to visitors, who can see the cannon batteries and dark dungeons. The fortress also offers a wide view of the Maracaibo Strait and bears witness to Venezuela's colonial defensive architecture.",
      es: "El Castillo de San Carlos de la Barra se sitúa sobre el acceso al Golfo de Venezuela y al Lago de Maracaibo. Su llamativa forma de estrella es un ejemplo clásico de la arquitectura defensiva de la época colonial española. Sirvió como barrera crítica contra las incursiones de piratas y flotas extranjeras que intentaban conquistar el acceso al lago, de gran importancia económica. Hoy es un testigo mudo de la historia militar en una de las vías fluviales históricamente más importantes del país.",
      pt: "O Castelo de São Carlos da Barra ergue-se sobre o acesso ao Golfo da Venezuela e ao Lago de Maracaibo. A sua forma marcante de estrela é um exemplo clássico da arquitetura de defesa do período colonial espanhol. Serviu como uma barreira crítica contra ataques de piratas e frotas estrangeiras que tentavam conquistar o acesso economicamente importante ao lago. Hoje é uma testemunha silenciosa da história militar numa das vias navegáveis historicamente mais importantes do país.",
      fr: "Le fort de San Carlos de la Barra surplombe l'accès au golfe du Venezuela et au lac Maracaibo. Sa forme en étoile frappante est un exemple classique de l'architecture défensive de l'ère coloniale espagnole. Il servait de barrière critique contre les incursions de pirates et de flottes étrangères tentant de conquérir l'accès au lac, économiquement vital. Aujourd'hui, il est un témoin muet de l'histoire militaire sur l'une des voies navigables les plus importantes du pays.",
    },
