      de: ["Ort des Kongresses von Angostura 1819.", "Befindet sich in Ciudad Bolívar."],
      hu: ["Az 1819-es angosturai kongresszus helyszíne.", "Ciudad Bolívarban található."],
      ro: ["Locul Congresului de la Angostura din 1819.", "Situată în Ciudad Bolívar."],
