    coords: [-64.1685, 10.8252],
    name: {
      de: "Ruinen von Nueva Cádiz",
      hu: "Nueva Cádiz Romjai",
      ro: "Ruinele din Nueva Cádiz",
      en: "Ruins of Nueva Cádiz"},
    image: "/poi-images/venezuela-ruinas-nueva-cadiz-history-v2.webp",
    description: {
      de: "Die Überreste der ersten spanischen Siedlung in Südamerika auf der kleinen Insel Cubagua.",
      hu: "Az első dél-amerikai spanyol település maradványai a kis Cubagua-szigeten.",
      ro: "Rămășițele primei așezări spaniole din America Sud de pe mica insulă Cubagua.",
      en: "The remains of the first Spanish settlement in South America on the small island of Cubagua.",
      es: "Los restos del primer asentamiento español en Sudamérica, en la pequeña isla de Cubagua.",
      pt: "Os restos do primeiro povoado espanhol na América do Sul, na pequena ilha de Cubagua.",
      fr: "Les vestiges de la première colonie espagnole en Amérique du Sud sur la petite île de Cubagua.",
    },
    descriptionAdvanced: {
      de: "Die Ruinen von Nueva Cádiz auf der Insel Cubagua markieren den Ort der ersten spanischen Stadt in Südamerika und sind ein Zeugnis für den rasanten Aufstieg und Fall der frühen Kolonisation. Gegründet um das Jahr 1500 (offiziell als Stadt 1528), wurde Nueva Cádiz durch den massiven Abbau von Perlen in den umliegenden Gewässern zu einer der reichsten Siedlungen der Neuen Welt. Die Stadt verfügte über Steinhäuser, Kirchen und ein Rathaus, was für die damalige Zeit in der Region außergewöhnlich war. Doch der Reichtum war von kurzer Dauer: Raubbau an den Perlenbänken, die Versklavung der indigenen Bevölkerung und schließlich ein verheerendes Erdbeben sowie eine Flutwelle im Jahr 1541 führten zum Untergang der Stadt. Nach weiteren Angriffen durch französische Piraten im Jahr 1543 wurde der Ort endgültig verlassen. Heute sind nur noch die Grundmauern und einige archäologische Überreste sichtbar, die in der kargen Wüstenlandschaft von Cubagua liegen. Die Stätte ist ein wichtiges Ziel für Historiker, um die Anfänge des spanischen Imperiums und die ökologischen Folgen der frühen Rohstoffausbeutung zu untersuchen.",
      hu: "Nueva Cádiz romjai Cubagua szigetén Dél-Amerika legelső spanyol városának maradványait őrizik, amely a korai gyarmati korszak egyik leggyorsabban felemelkedő és legtragikusabb sorsú települése volt. A várost 1500 körül alapították a rendkívül gazdag gyöngylelőhelyek kiaknázására, és 1528-ban kapott hivatalos városi rangot V. Károly császártól. Fénykorában Nueva Cádiz az Újvilág egyik leggazdagabb központja volt, kőházakkal, városházával és templomokkal, ami ritkaságnak számított a 16. századi Karib-térségben. A város bukását több tényező okozta: a gyöngytelepek kimerülése, az őslakos kényszermunkások pusztulása, majd végül 1541-ben egy pusztító földrengés és az azt követő szökőár tette lakhatatlanná. 1543-ban francia kalózok felgyújtották a még álló épületeket, ami után a várost végleg elhagyták. Ma a sivatagi tájban csak az épületek alapjai és néhány faragott kőtömb látható, amelyek néma tanúi az egykori gazdagságnak. A régészeti lelőhely kulcsfontosságú a korai spanyol gazdaságtörténet és a gyarmati urbanizáció kutatása szempontjából.",
      ro: "Ruinele Nueva Cádiz, situate pe insula Cubagua, reprezintă vestigiile primului oraș fondat de spanioli în America de Sud, fiind un sit de o importanță arheologică excepțională. Întemeiat în jurul anului 1500 pentru exploatarea intensivă a perlelor, orașul a primit statutul oficial de municipalitate în 1528, devenind rapid unul dintre cele mai prospere centre din Lumea Nouă. Prosperitatea sa a fost clădită pe munca forțată a populației indigene și pe bogăția imensă extrasă din adâncurile Mării Caraibilor. Cu toate acestea, declinul a fost la fel de rapid ca ascensiunea sa: epuizarea bancurilor de perle și o serie de dezastre naturale, inclusiv un cutremur devastator și un tsunami în 1541, au dus la ruinarea orașului. După un atac final al piraților francezi în 1543, așezarea a fost abandonată definitiv, fiind înghițită de nisipurile aride ale insulei. Astăzi, vizitatorii pot vedea fundațiile clădirilor din piatră și resturi ale arhitecturii coloniale timpurii într-un peisaj deșertic izolat. Nueva Cádiz rămâne un simbol al impactului ecologic și social al primei etape de colonizare spaniolă în emisfera vestică.",
      en: "The ruins of Nueva Cádiz on Cubagua Island mark the site of the first Spanish city founded in South America, offering a haunting glimpse into the early colonial era. Established around 1500 primarily for pearl fishing, the settlement grew so rapidly that it was granted a royal charter as a city in 1528. At its peak, it was one of the wealthiest ports in the New World, boasting stone mansions, a convent, and a municipal hall in an otherwise undeveloped region. However, the city's reliance on pearl exploitation led to its eventual downfall as the oyster beds were depleted and the indigenous labor force decimated. A catastrophic earthquake and subsequent tidal wave in 1541 destroyed much of the infrastructure, and a final assault by French pirates in 1543 led to its total abandonment. Today, the archaeological site reveals the foundations of these structures preserved by the arid climate of the desert island. It serves as a significant historical site for understanding the logistical and economic challenges faced by the first Spanish settlers in the Caribbean. The stark landscape and scattered ruins tell a story of rapid environmental and social collapse during the 16th century.",
      es: "Nueva Cádiz, en la isla de Cubagua, es un sitio arqueológico de valor incalculable. Fue el primer intento oficial de la Corona española de establecer un asentamiento permanente en el continente sudamericano. La ciudad floreció brevemente gracias al comercio de perlas antes de ser casi completamente destruida en 1541 por un desastre natural, un tsunami. Hoy, las ruinas son un lugar que da testimonio de los primeros y a menudo duros días de la expansión española.",
      pt: "Nueva Cádiz, na ilha de Cubagua, é um sítio arqueológico de valor inestimável. Foi a primeira tentativa oficial da Coroa Espanhola de estabelecer um povoado permanente no continente sul-americano. A cidade floresceu brevemente através do comércio de pérolas antes de ser quase completamente destruída em 1541 por uma catástrofe natural, um tsunami. Atualmente, as ruínas são um local que testemunha os primeiros e muitas vezes difíceis dias da expansão espanhola.",
      fr: "Nueva Cádiz, sur l'île de Cubagua, est un site archéologique d'une valeur inestimable. Ce fut la première tentative officielle de la Couronne espagnole d'établir une colonie permanente sur le continent sud-américain. La ville a brièvement prospéré grâce au commerce des perles avant d'être presque entièrement détruite en 1541 par une catastrophe naturelle, un tsunami. Aujourd'hui, les ruinas sont un lieu qui témoigne des premiers jours, souvent rudes, de l'expansion espagnole.",
    },
