    image: "/poi-images/venezuela-iglesia-san-francisco-yare-history-v2.webp",
    description: {
      de: "Eine koloniale Kirche, die weltbekannt für die traditionellen Feierlichkeiten der tanzenden Teufel ist.",
      hu: "Gyarmati templom, amely világszerte ismert a táncoló ördögök hagyományos ünnepségeiről.",
      ro: "O biserică colonială renumită în întreaga lume pentru festivitățile tradiționale ale dracilor dansatori.",
      en: "A colonial church world-renowned for the traditional festivities of the dancing devils.",
      es: "Una iglesia colonial de fama mundial por las celebraciones tradicionales der los Diablos Danzantes.",
      pt: "Uma igreja colonial mundialmente famosa pelas celebrações tradicionais dos Diabos Dançantes.",
      fr: "Une église coloniale mondialement connue pour les célébrations traditionnelles des Diables Dansants.",
    },
    descriptionAdvanced: {
      de: "Die Kirche San Francisco de Yare ist ein bedeutendes religiöses Denkmal in San Francisco de Yare im Bundesstaat Miranda, Venezuela. Die im 18. Jahrhundert errichtete Kirche ist vor allem durch ihre Verbindung zu den \"Tanzenden Teufeln von Yare\" (Diablos Danzantes de Yare) bekannt, einem religiösen Fest, das an Fronleichnam stattfindet. Diese Tradition, die afrikanische, indigene und spanische Einflüsse verbindet, wurde 2012 von der UNESCO als immaterielles Kulturerbe anerkannt. Die Kirche selbst weist einen kolonialen Baustil mit einer schlichten Fassade und einem Glockenturm auf. Im Inneren beherbergt sie religiöse Bilder und Altäre, die für das spirituelle Leben der örtlichen Gemeinschaft von zentraler Bedeutung sind. Im Laufe der Jahrhunderte wurde das Gebäude mehrfach renoviert, um seinen historischen Wert zu erhalten, und dient heute als Symbol der regionalen Identität im Tuy-Tal.",
      hu: "A San Francisco de Yare-templom egy jelentős vallási műemlék a venezuelai Miranda államban található San Francisco de Yare városában. A 18. században épült templom leginkább a \"Yarei Táncoló Ördögök\" (Diablos Danzantes de Yare) hagyományáról ismert, amely egy Úrnapján tartott vallási ünnep. Ez a tradíció, amely afrikatei, őslakos és spanyol hatásokat ötvöz, 2012-ben került fel az UNESCO szellemi kulturális örökség listájára. Maga a templom gyarmati építészeti stílust mutat, egyszerű homlokzattal és egyetlen harangtoronnyal. Belsejében számos vallási szobor és oltár található, amelyek központi szerepet játszanak a helyi közösség hitéletében. Az évszázadok során az épületet többször felújították történelmi és kulturális értékének megőrzése érdekében, és ma a Tuy-völgy lakóinak regionális identitását és hitét jelképezi.",
      ro: "Biserica San Francisco de Yare este un monument religios semnificativ situat în San Francisco de Yare, statul Miranda, Venezuela. Construită în secolul al XVIII-lea, biserica este faimoasă în special pentru asocierea sa cu „Diavolii Dansatori din Yare” (Diablos Danzantes de Yare), un festival religios care are loc de Corpus Christi. Această tradiție, care îmbină influențe africane, indigene și spaniole, a fost recunoscută de UNESCO ca patrimoniu cultural imaterial în 2012. Biserica în sine prezintă un stil arhitectural colonial, cu o fațadă simplă și un singur turn clopotniță. În interior, adăpostește numeroase imagini religioase și altare care sunt centrale pentru viața spirituală a comunității locale. De-a lungul secolelor, clădirea a suferit diverse renovări pentru a-și păstra valoarea istorică și culturală, servind ca un simbol al identității regionale și al credinței pentru locuitorii din Valea Tuy.",
      en: "The Church of San Francisco de Yare is a significant religious landmark located in San Francisco de Yare, Miranda State, Venezuela. Constructed in the 18th century, it is most famous for its association with the \"Dancing Devils of Yare\" (Diablos Danzantes de Yare), a religious festival that takes place on Corpus Christi. This tradition, which blends African, Indigenous, and Spanish influences, was recognized by UNESCO as Intangible Cultural Heritage in 2012. The church itself features a colonial architectural style with a simple yet elegant facade and a single bell tower. Inside, it houses several religious images and altars that are central to the local community's spiritual life. Over the centuries, the building has undergone various renovations to preserve its historical and cultural value, serving as a symbol of regional identity and faith for the people of the Tuy Valley.",
      es: "La Iglesia de San Francisco de Yare es el epicentro de una de las festividades religiosas más importantes de Venezuela: 'Los Diablos Danzantes de Yare'. Durante la fiesta del Corpus Christi, todo el pueblo que rodea esta iglesia se convierte en el escenario de un espectáculo místico que simboliza la victoria del bien sobre el mal. Esta tradición está reconocida por la UNESCO como Patrimonio Cultural Inmaterial. La iglesia misma es una estructura sencilla pero cargada de historia que ha conservado esta riqueza espiritual y la cohesión comunitaria durante siglos.",
      pt: "A Igreja de San Francisco de Yare é o epicentro de uma das festas religiosas mais importantes da Venezuela: 'Os Diabos Dançantes de Yare'. Durante a festa de Corpus Christi, toda a aldeia em redor desta igreja transforma-se no palco de um espetáculo místico que simboliza a vitória do bem sobre o mal. Esta tradição é reconhecida pela UNESCO como Património Cultural Imaterial. A própria igreja é uma estrutura simples mas histórica que preservou esta riqueza espiritual e a coesão da comunidade ao longo de séculos.",
      fr: "L'église de San Francisco de Yare est l'épicentre de l'une des fêtes religieuses les plus importantes du Venezuela : « Les Diables Dansants de Yare ». Pendant la fête du Corpus Christi, tout le village entourant cette église se transforme en scène pour un spectacle mystique symbolisant la victoire du bien sur le mal. Cette tradition est reconnue par l'UNESCO comme patrimoine culturel immatériel. L'église elle-même est une structure simple mais historique qui a préservé cette richesse spirituelle et la cohésion de la communauté à travers les siècles.",
    },
