      hu: ["A templom építése 1714-ben fejeződött be.", "Ez a központja a yarei táncoló ördögök ünnepségének.", "Az UNESCO 2012-ben a szellemi világörökség részévé nyilvánította a rítust.", "A templom védőszentje Paolai Szent Ferenc.", "Az épület Miranda államban, a Tuy-völgyben található.", "Építészete a venezuelai gyarmati stílus egyik jellegzetes példája."],
