      en: ["The church construction was completed in 1714.", "It is the primary center for the Dancing Devils of Yare celebration.", "UNESCO declared the tradition a World Heritage in 2012.", "The patron saint of the church is Saint Francis of Paola.", "The building is located in Miranda State, in the Tuy Valley.", "The architecture is a classic example of Venezuelan colonial style."],
      es: ["La fiesta de los Diablos Danzantes de Yare es Patrimonio de la Humanidad de la UNESCO desde 2012.", "La iglesia sirve como punto de partida para las procesiones solemnes de los bailarines.", "El origen sincrético de la fiesta (mezcla de tradiciones católicas y africanas) la hace única.", "El edificio es parte integrante de la identidad local de San Francisco de Yare."],
      pt: ["A festa dos Diabos Dançantes de Yare é Património Mundial da UNESCO desde 2012.", "A igreja serve como ponto de partida para as procissões solenes dos dançarinos.", "A origem sincrética da festa (mistura de tradições católicas e africanas) torna-a única.", "O edifício é uma parte integrante da identidade local de San Francisco de Yare."],
